#pragma once
#include "ModWire54.h"
#include <math.h>
#include <stdlib.h>
#include <string.h>
namespace mod54 {
inline float bound(float x,float a,float b){return x<a?a:x>b?b:x;}
inline float curve(float x,int c,int maximum){x=bound(x,0,1);float p=1+(maximum-1)*abs(c)/100.f;return c>0?1-powf(1-x,p):c<0?powf(x,p):x;}
inline float held(float age,const Params&p){if(age<p.hold)return 0;age-=p.hold;if(p.attack&&age<p.attack)return curve(age/p.attack,p.ac,p.maximum);age-=p.attack;float s=p.sustain/127.f;return p.decay&&age<p.decay?1-(1-s)*curve(age/p.decay,p.dc,p.maximum):s;}
inline float envelope(float age,const Params&p){if(age<0||age<p.decay)return 0;age-=p.decay;if(p.attack&&age<p.attack)return age/p.attack;age-=p.attack;if(!p.release||age>=p.release)return 0;float x=age/p.release,power=powf(32.f,abs(p.rc)/100.f);return p.rc>=0?1-powf(x,power):powf(1-x,power);}
struct State {Source source{};int64_t delayBegin58=-1;uint32_t delayGate58=0;double phase=0;uint32_t wall=0;float period=1,value=0;bool freeValid=false,cached=false;uint16_t identity=65535;uint64_t sample=0;Params sampled{};};
struct Address {uint16_t number;int16_t base=0,lock=0,last=0;float sum=0;uint16_t count=0;uint8_t kind,port,channel,track=255;bool used=false,locked=false,known=false;uint32_t sent=0;};
struct Engine {
 bool (*delayKeep55)(uint8_t,uint8_t,uint8_t,uint16_t)=nullptr;
 int (*delayBase55)(uint8_t,uint8_t,uint8_t,uint16_t,int)=nullptr;
 int (*delayParam55)(uint16_t,uint8_t,uint8_t,int)=nullptr;
 int baseValue55(const Address&a)const{int base=a.locked?a.lock:a.base;return delayBase55?delayBase55(a.kind,a.port,a.channel,a.number,base):base;}
 Params params[N]{};State states[N]{};Route routes[R]{};Address addresses[A]{};
 float incoming[N][8]{},incomingParam[N][5]{};uint16_t counts[N][8]{},paramCounts[N][5]{};
 int16_t first[N]{},next[R]{},routeAddress[R]{};
 struct Phase {double phase;uint32_t wall;float period;uint16_t identity;bool valid;};Phase phases[N]{};
 uint8_t order[N]{};uint16_t orderCount=0;bool dirty=true,valid=true;Clock clock{};uint32_t anchor=0,errors=0,computed=0;bool suspended=true;uint16_t outputCursor=0;
 void begin(){for(unsigned k=0;k<N;++k){auto&s=states[k];phases[k]={s.phase,s.wall,s.period,s.identity,s.freeValid&&bool(params[k].enabled)};}memset(params,0,sizeof(params));memset(routes,0,sizeof(routes));for(auto&a:addresses){if(a.used&&delayKeep55&&delayKeep55(a.kind,a.port,a.channel,a.number)){a.sum=0;a.count=0;a.locked=false;}else a={};}dirty=true;suspended=true;for(auto&s:states)s.cached=false;}
 void reset(){suspended=true;memset(params,0,sizeof(params));memset(states,0,sizeof(states));memset(routes,0,sizeof(routes));memset(addresses,0,sizeof(addresses));orderCount=0;dirty=true;clock={};}
 int address(uint8_t kind,uint8_t port,uint8_t channel,uint16_t number,bool create=true){int free=-1;for(unsigned i=0;i<A;++i){auto&a=addresses[i];if(!a.used){if(free<0)free=i;continue;}if(a.kind==kind&&a.port==port&&a.channel==channel&&a.number==number)return i;}if(create&&free>=0){auto&a=addresses[free];a={};a.used=true;a.kind=kind;a.port=port;a.channel=channel;a.number=number;return free;}return -1;}
 bool configure(const Config&c){if(c.id<N&&states[c.id].identity==c.identity&&!memcmp(&params[c.id],&c.p,sizeof(c.p)))return true;if(c.id>=N||c.p.lfo>1||c.p.enabled>1||!c.p.rat||!c.p.cycle||!c.p.interval||c.p.maximum<1||c.p.maximum>100||c.p.shape>4||c.p.mode>6||c.p.env>4||c.p.delay58>2)return false;if(suspended){states[c.id].freeValid=false;for(auto&f:phases)if(f.identity==c.identity&&f.valid){states[c.id].phase=f.phase;states[c.id].wall=f.wall;states[c.id].period=f.period;states[c.id].freeValid=true;break;}}else if(states[c.id].identity!=c.identity||params[c.id].mode!=c.p.mode)states[c.id].freeValid=false;if(!states[c.id].freeValid&&c.seedValid&&c.periodSeed>0){states[c.id].phase=c.phaseSeed;states[c.id].wall=c.wallSeed;states[c.id].period=c.periodSeed;states[c.id].freeValid=true;}if(states[c.id].identity!=c.identity){states[c.id].delayBegin58=-1;states[c.id].delayGate58=0;}states[c.id].identity=c.identity;states[c.id].cached=false;params[c.id]=c.p;dirty=true;return true;}
 bool route(const Route&r){if(r.id<R&&!memcmp(&routes[r.id],&r,sizeof(r)))return true;if(r.id>=R||r.source>=N||r.kind>6||r.port>7||r.channel>15||(r.kind>=5&&(r.target>=N||r.slot>7))||r.sourceSlot>7||r.locked>1||(r.kind==0&&r.number>127)||(r.kind==1&&r.number)||(r.kind==4&&r.number>3)||(r.kind>=2&&r.kind<=3&&r.number>16383))return false;if(r.enabled&&r.kind<5&&address(r.kind,r.port,r.channel,r.number)<0)return false;routes[r.id]=r;dirty=true;if(r.enabled&&r.kind<5){int i=address(r.kind,r.port,r.channel,r.number);if(i<0)return false;addresses[i].base=r.base;addresses[i].track=r.track;addresses[i].locked=r.locked;addresses[i].lock=r.lockValue;}return true;}
 bool source(const Source&s){if(s.id>=N||s.active>1)return false;if(memcmp(&states[s.id].source,&s,sizeof(s)))states[s.id].cached=false;states[s.id].source=s;return true;}
 void base(const Base&b,bool locked=false,bool active=false){for(unsigned port=0;port<8;++port)if(b.mask&(1u<<port)){int i=address(b.kind,port,b.channel,b.number);if(i<0){++errors;continue;}auto&a=addresses[i];if(locked){a.locked=active;a.lock=b.value;}else a.base=b.value;a.known=false;}}
 void rebuild(){memset(first,255,sizeof(first));memset(next,255,sizeof(next));memset(routeAddress,255,sizeof(routeAddress));for(unsigned i=0;i<R;++i)if(routes[i].enabled){auto&r=routes[i];next[i]=first[r.source];first[r.source]=i;if(r.kind<5)routeAddress[i]=address(r.kind,r.port,r.channel,r.number,false);}uint16_t degree[N]={};orderCount=0;unsigned total=0;for(unsigned k=0;k<N;++k)total+=params[k].enabled;for(auto&r:routes)if(r.enabled&&r.kind>=5&&params[r.source].enabled&&params[r.target].enabled)++degree[r.target];for(unsigned k=0;k<N;++k)if(params[k].enabled&&!degree[k])order[orderCount++]=k;for(unsigned i=0;i<orderCount;++i)for(auto&r:routes)if(r.enabled&&r.kind>=5&&r.source==order[i]&&params[r.target].enabled&&!--degree[r.target])order[orderCount++]=r.target;valid=total==orderCount;dirty=false;}
 float value(unsigned k,Params p,double tick,uint32_t wall){tick=floor(tick);auto&s=states[k];auto src=s.source;if(p.delay58&&s.delayBegin58>src.noteBegin){src.noteBegin=s.delayBegin58;if(p.mode==0||p.mode==5){src.begin=s.delayBegin58;src.gate=s.delayGate58;}}if(!src.active)return 0;double at=tick;unsigned rat=p.rat?p.rat:1;double origin=0;if(p.mode==3||p.mode==4){int span=(p.mode==3?1536:384)*(p.lfo?p.interval:1);origin=floor(at/span)*span;}if(p.mode!=2)at-=fmod(at-origin,rat);double latest=src.begin;unsigned gate=src.gate;
  if(p.mode==3||p.mode==4){latest=origin;if(!p.lfo)gate=p.hold+p.attack+p.decay>0?p.hold+p.attack+p.decay:1;}
  if(!p.lfo){if(latest<0)return 0;float age=at-latest;if(p.hold<0){age=tick-latest;if(age<=gate&&age>=p.hold)age=p.hold+floorf((age-p.hold)/rat)*rat;else if(age>gate)age=gate+floorf((age-gate)/rat)*rat;}if(age<=gate)return held(age,p);return !p.release||age>=(double)gate+p.release?0:held(gate,p)*(1-curve((age-gate)/p.release,p.rc,p.maximum));}
  double elapsed=at-latest,phase=0;if(p.mode!=2&&latest<0)return 0;if(p.mode==6&&at>=latest+gate)return 0;float tickMs=clock.tickUs/1000.f;
  if(p.mode==2){uint32_t sampled=wall-wall%rat;float period=p.cycle*(p.ms?1.f:tickMs);if(!s.freeValid){s.phase=fmod(sampled/period,1.);s.freeValid=true;}else s.phase=fmod(s.phase+(uint32_t)(sampled-s.wall)/s.period,1.);s.wall=sampled;s.period=period;phase=s.phase;elapsed=phase*p.cycle;}else {if(p.ms)elapsed=floor(elapsed*tickMs);phase=fmod(elapsed,p.cycle)/p.cycle;}
  float age=p.ms?elapsed/tickMs:elapsed;if(p.env==2)age=src.noteBegin<0?-1:at-src.noteBegin;else if(p.env>=3)age=fmod(at,(p.env==3?1536:384)*p.interval);else if(p.env==1)age=p.ms?fmod(elapsed,p.cycle)/tickMs:fmod(elapsed,p.cycle);
  float gain=p.env?envelope(age,p):1;phase=fmod(phase+p.phase/360.f+1,1.);return gain*(p.shape==1?(phase<.5?1:-1):p.shape==2?phase*2-1:p.shape==3?1-phase*2:p.shape==4?sin(phase*6.28318530718):phase<.5?phase*4-1:3-phase*4);
 }
 void evaluate(uint32_t now){if(suspended)return;if(dirty)rebuild();if(!valid)return;double tick=clock.tick+(clock.playing?(uint32_t)(now-anchor)/(double)(clock.tickUs?clock.tickUs:1):0);uint32_t wall=clock.wall+(uint32_t)(now-anchor)/1000;
  memset(incoming,0,sizeof(incoming));memset(incomingParam,0,sizeof(incomingParam));memset(counts,0,sizeof(counts));memset(paramCounts,0,sizeof(paramCounts));for(auto&a:addresses){a.sum=0;a.count=0;}
  for(unsigned n=0;n<orderCount;++n){unsigned k=order[n];auto p=params[k];if(delayParam55){if(p.lfo){p.cycle=bound(delayParam55(states[k].identity,5,0,p.cycle),1,3599999);p.phase=bound(delayParam55(states[k].identity,5,1,p.phase),0,360);}else{p.hold=bound(delayParam55(states[k].identity,5,0,p.hold),-384,65535);p.attack=bound(delayParam55(states[k].identity,5,1,p.attack),0,65535);p.decay=bound(delayParam55(states[k].identity,5,2,p.decay),0,65535);p.sustain=bound(delayParam55(states[k].identity,5,3,p.sustain),0,127);p.release=bound(delayParam55(states[k].identity,5,4,p.release),0,65535);}}for(unsigned j=0;j<(p.lfo?2:5);++j)if(paramCounts[k][j]){int base=p.lfo?(j?p.phase:p.cycle):j==0?p.hold:j==1?p.attack:j==2?p.decay:j==3?p.sustain:p.release;int v=lroundf(base+incomingParam[k][j]/paramCounts[k][j]);if(p.lfo){if(j)p.phase=bound(v,0,360);else p.cycle=bound(v,1,3599999);}else{v=bound(v,0,j==3?127:65535);if(!j)p.hold=v;else if(j==1)p.attack=v;else if(j==2)p.decay=v;else if(j==3)p.sustain=v;else p.release=v;}}
   auto&st=states[k];uint64_t sample=p.mode==2?wall/p.rat:(uint64_t)tick/p.rat;float v=st.value;if(!st.cached||st.sample!=sample||memcmp(&st.sampled,&p,sizeof(p))){v=value(k,p,tick,wall);st.value=v;st.sample=sample;st.sampled=p;st.cached=true;++computed;}
   for(int index=first[k];index>=0;index=next[index]){auto&r=routes[index];float depth=(delayParam55?delayParam55(states[k].identity,6,r.sourceSlot,r.depth):r.depth)+(counts[k][r.sourceSlot]?incoming[k][r.sourceSlot]/counts[k][r.sourceSlot]:0);if(!depth||!states[k].source.active)continue;int limit=r.limit?r.limit:r.kind==1?8192:r.kind==3?16383:r.kind==4?4095:r.kind==5?32767:r.kind==6?8191:127;depth=bound(depth,-limit,limit==8192?8191:limit);float x=v*depth;if(r.kind==5){if(r.slot<5){incomingParam[r.target][r.slot]+=x;++paramCounts[r.target][r.slot];}}else if(r.kind==6){incoming[r.target][r.slot]+=x;++counts[r.target][r.slot];}else{int i=routeAddress[index];if(i>=0){addresses[i].sum+=x;++addresses[i].count;}}}
  }
 }
 template<class Emit>void output(uint32_t now,Emit emit){if(suspended)return;for(unsigned visited=0;visited<A;++visited){auto&a=addresses[outputCursor];outputCursor=(outputCursor+1)%A;if(!a.used)continue;int lo=a.kind==1?-8192:0,hi=a.kind==1?8191:a.kind==3?16383:a.kind==4?4095:127;int v=bound(baseValue55(a)+(a.count?lroundf(a.sum/a.count):0),lo,hi);if((!a.known||v!=a.last)&&(!a.known||(uint32_t)(now-a.sent)>=2000)){if(emit(a,v)){a.last=v;a.sent=now;a.known=true;}else return;}}}
};
}

